import React, { useState, useEffect } from 'react';
import { ReactMediaRecorder } from 'react-media-recorder';
import { FFmpeg } from '@ffmpeg/ffmpeg';
import { Mic, Loader2, CheckCircle, XCircle, Pause, X, Check } from 'lucide-react';

const ffmpeg = new FFmpeg();

export default function VoiceBookingRecorder() {
  const [blobUrl, setBlobUrl] = useState(null);
  const [isRecording, setIsRecording] = useState(false);
  const [bookingInfo, setBookingInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [startTime, setStartTime] = useState(null);
  const [elapsed, setElapsed] = useState("00:00.00");

  useEffect(() => {
    let timer;
    if (isRecording) {
      setStartTime(Date.now());
      timer = setInterval(() => {
        const delta = Date.now() - startTime;
        const seconds = ((delta / 1000) % 60).toFixed(2).padStart(5, '0');
        const minutes = Math.floor(delta / 60000).toString().padStart(2, '0');
        setElapsed(`${minutes}:${seconds}`);
      }, 100);
    } else {
      clearInterval(timer);
    }
    return () => clearInterval(timer);
  }, [isRecording, startTime]);

  useEffect(() => {
    if (blobUrl) sendAudioToBackend(blobUrl);
  }, [blobUrl]);

  const convertWebMToWav = async (webmBlob) => {
    await ffmpeg.load();
    const data = await webmBlob.arrayBuffer();
    ffmpeg.writeFile('input.webm', new Uint8Array(data));
    await ffmpeg.exec(['-i', 'input.webm', 'output.wav']);
    const wavData = await ffmpeg.readFile('output.wav');
    return new Blob([wavData.buffer], { type: 'audio/wav' });
  };

  const sendAudioToBackend = async (url) => {
    setLoading(true);
    try {
      const response = await fetch(url);
      const webmBlob = await response.blob();
      const wavBlob = await convertWebMToWav(webmBlob);
      const formData = new FormData();
      formData.append("audio", wavBlob, "audio.wav");

      const res = await fetch("http://localhost:3001/api/voice-booking", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();
      setBookingInfo(data);
    } catch (err) {
      console.error("❌ Error sending audio:", err);
      setBookingInfo({ message: "An error occurred." });
    }
    setLoading(false);
  };

  const getInstructionText = () => {
    if (loading) return "Analyzing your voice...";
    if (isRecording) return "Speak clearly to book your appointment...";
    return "Tap the mic to record your booking request.";
  };

  return (
    <ReactMediaRecorder
      audio={{ channelCount: 1 }}
      onStop={(url) => setBlobUrl(url)}
      render={({ startRecording, stopRecording, mediaBlobUrl }) => (
        <div className="min-h-screen bg-gradient-to-br from-purple-500 to-indigo-700 flex items-center justify-center px-4">
          <div className="bg-white/20 backdrop-blur-xl rounded-3xl shadow-2xl p-6 w-full max-w-xs space-y-6 text-center">

            {/* Header */}
            <div className="flex justify-between items-center">
              <button className="bg-white rounded-full p-2 shadow">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path d="M4 6h16M4 12h16M4 18h16"></path></svg>
              </button>
              <h1 className="text-sm font-semibold text-white">Voice Record</h1>
              <img src="https://i.pravatar.cc/100" className="w-8 h-8 rounded-full border" />
            </div>

            {/* Mic Button */}
            <div className="flex justify-center mt-2">
              <button
                onClick={() => {
                  if (!isRecording) {
                    setIsRecording(true);
                    setBlobUrl(null);
                    setBookingInfo(null);
                    startRecording();
                  } else {
                    setIsRecording(false);
                    stopRecording();
                  }
                }}
                className={`p-6 rounded-full shadow-lg transition-all duration-300 ${
                  isRecording ? 'bg-red-500 animate-pulse' : 'bg-gradient-to-br from-orange-400 to-red-500'
                }`}
              >
                <Mic className="w-10 h-10 text-white" />
              </button>
            </div>

            {/* Timer */}
            <div className="text-2xl font-mono text-white">{elapsed}</div>

            {/* Waveform placeholder */}
            <div className="h-24 bg-white/40 rounded-xl shadow-inner relative overflow-hidden">
              <div className="absolute top-0 left-1/2 transform -translate-x-1/2 h-full w-1 bg-red-500"></div>
            </div>

            {/* Audio & Result */}
            {mediaBlobUrl && (
              <audio src={mediaBlobUrl} controls className="w-full rounded-xl shadow-inner mt-4" />
            )}

            {loading && (
              <div className="flex items-center justify-center text-white space-x-2">
                <Loader2 className="animate-spin" />
                <span>Processing...</span>
              </div>
            )}

            {bookingInfo && (
              <div className="bg-white p-4 rounded-lg shadow space-y-2 text-sm text-gray-700">
                <p><strong>Transcript:</strong> {bookingInfo.transcript}</p>
                <p><strong>Intent:</strong> {bookingInfo.intent}</p>

                {bookingInfo.slot ? (
                  <div className="text-green-600">
                    <CheckCircle className="inline mr-1" /> Booking Confirmed!
                    <p><strong>Service:</strong> {bookingInfo.slot.service}</p>
                    <p><strong>Stylist:</strong> {bookingInfo.slot.stylist}</p>
                    <p><strong>Branch:</strong> {bookingInfo.slot.branch}</p>
                    <p><strong>Date/Time:</strong> {new Date(bookingInfo.slot.datetime).toLocaleString()}</p>
                  </div>
                ) : (
                  <div className="text-red-600">
                    <XCircle className="inline mr-1" /> {bookingInfo.message}
                  </div>
                )}
              </div>
              
            )}
          </div>
          <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 text-white text-sm bg-black/50 px-4 py-2 rounded-full shadow-md animate-fade-forward">
  {getInstructionText()}
</div>
        </div>
      )}
    />
  );
}
